(()=>{let index=0;const images=window.ZINE_IMAGES||[],photo=document.querySelector('.zine-photo'),counter=document.querySelector('.counter'),carousel=document.querySelector('.zine-carousel');const render=()=>{photo.src=images[index];counter.textContent=`${index+1} / ${images.length}`};const previous=()=>{index=(index+images.length-1)%images.length;render()};const next=()=>{index=(index+1)%images.length;render()};document.querySelector('.prev')?.addEventListener('click',previous);document.querySelector('.next')?.addEventListener('click',next);let startX=0,startY=0;carousel?.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;startX=e.clientX;startY=e.clientY});carousel?.addEventListener('pointerup',e=>{const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)>42&&Math.abs(dx)>Math.abs(dy))dx>0?previous():next()});document.querySelector('.zine-language')?.addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='En'?'Ru':'En'});document.querySelector('.zine-burger')?.addEventListener('click',()=>location.href='index.html')})()
